                d=os.read(fd, 65536)
            except OSError:
                break
            if not d: break
            out += d
        if keys and time.time()-start > delays*(len(sent)+1):
            if sent and sent[-1]=='END': break
            if len(sent)<len(keys):
                k=keys[len(sent)]
                os.write(fd, k if isinstance(k,bytes) else k.encode())
                sent.append(k)
        if time.time()-start > dur + delays*max(1,len(keys)):
            break
    try:
        os.write(fd,b'q')
    except OSError: pass
    try:
        os.close(fd)
    except OSError: pass
    try:
        os.waitpid(pid, os.WNOHANG)
    except Exception: pass
    return out
if __name__=='__main__':
