                i+=1; continue
            elif ch=='\r': self.c=0; i+=1; continue
            elif ch=='\n': self.r+=1; i+=1; continue
            elif ch=='\x08': self.c=max(0,self.c-1); i+=1; continue
            else:
                self.put(ch); i+=1; continue
    def csi(self,params,fin):
        p=[int(x) if x.isdigit() else 0 for x in params.split(';')] if params and '?' not in params else []
        def p_(idx, default=1):
