            elif mode==0:
                for c in range(self.c,self.cols):
                    self.grid[self.r][c]=' '; self.attr[self.r][c]=None
                for r in range(self.r+1,self.rows):
                    self.grid[r]=[' ']*self.cols; self.attr[r]=[None]*self.cols
        elif fin=='K':
            mode=p[0] if p else 0
            if mode==0:
                for c in range(self.c,self.cols): self.grid[self.r][c]=' '; self.attr[self.r][c]=None
            elif mode==1:
                for c in range(0,self.c+1): self.grid[self.r][c]=' '; self.attr[self.r][c]=None
            else:
                self.grid[self.r]=[' ']*self.cols; self.attr[self.r]=[None]*self.cols
        elif fin=='m':
