                    elif 40<=v<=47: self.bg=v-40
                    elif v==49: self.bg=None
                    elif 100<=v<=107: self.bg=v-100+8
                    k+=1
    def esc(self,fin): pass
    def text(self):
        return [''.join(r) for r in self.grid]
    def dump(self):
        out=[]
        for r,row in enumerate(self.grid):
            line=''.join(row)
            out.append('%02d|%s|'%(r,line))
        return '\n'.join(out)
