import subprocess,time,re
def new(cwd, cmd='/workspace/executable', cols=100, rows=10, sess='q'):
    subprocess.run(['tmux','kill-session','-t',sess],capture_output=True)
    subprocess.run(['tmux','new-session','-d','-s',sess,'-x',str(cols),'-y',str(rows),
                    'cd %s && %s; echo EXIT=$?; sleep 600'%(cwd,cmd)],capture_output=True)
    time.sleep(0.5)
def send(sess,keys):
    for k in keys:
        subprocess.run(['tmux','send-keys','-t',sess,k],capture_output=True)
def cap(sess='q',esc=False):
    args=['tmux','capture-pane','-p','-t',sess]
    if esc: args.append('-e')
    o=subprocess.run(args,capture_output=True)
    return o.stdout.decode('utf8','replace')
def lines(sess='q'):
    return cap(sess).split('\n')
