{"command": "cd /tmp/rs && cat > nat.rs <<'EOF'
use std::cmp::Ordering;
use std::fs;

fn canonical(s: &[u8]) -> bool {
    if s.is_empty() { return false }
    if s.len() == 1 { return true }
    s[0] != b'0'
}
fn cmp_run(a: &[u8], b: &[u8]) -> Ordering {
    if canonical(a) && canonical(b) {
        let ta: &[u8] = if a[0]==b'0' { &a[1..] } else { a };
        let tb: &[u8] = if b[0]==b'0' { &b[1..] } else { b };
        match ta.len().cmp(&tb.len()) { Ordering::Equal => {}, o => return o }
        ta.cmp(tb)
    } else { a.cmp(b) }
}
fn natcmp(x: &str, y: &str) -> Ordering {
    let a = x.to_lowercase(); let b = y.to_lowercase();
    let (ab, bb) = (a.as_bytes(), b.as_bytes());
    let (mut i, mut j) = (0usize, 0usize);
    while i < ab.len() && j < bb.len() {
        let (ca, cb) = (ab[i], bb[j]);
        if ca.is_ascii_digit() && cb.is_ascii_digit() {
            let mut i2=i; while i2<ab.len() && ab[i2].is_ascii_digit() { i2+=1 }
            let mut j2=j; while j2<bb.len() && bb[j2].is_ascii_digit() { j2+=1 }
            let o = cmp_run(&ab[i..i2], &bb[j..j2]);
            if o != Ordering::Equal { return o }
            i=i2; j=j2;
        } else if ca != cb {
            return ca.cmp(&cb);
        } else { i+=1; j+=1 }
    }
    (ab.len()-i).cmp(&(bb.len()-j))
}
fn main(){
    let names: Vec<String> = std::env::args().skip(1).collect();
    let mut v = names.clone();
    v.sort_by(|x,y| natcmp(x,y));
    println!("{:?}", v);
}
