        let n = unsafe { read(0, b.as_mut_ptr(), b.len()) };
        if n <= 0 {
            return false;
        }
        self.buf.extend_from_slice(&b[..n as usize]);
        true
    }
    pub fn next(&mut self) -> Option<Key> {
        loop {
            if self.buf.is_empty() {
                if !self.read_more() {
                    return None;
                }
            }
            if let Some((k, used)) = parse(&self.buf) {
                self.buf.drain(..used);
                return Some(k);
            }
            if !self.read_more() {
                if self.buf.is_empty() {
                    return None;
                }
                // can't parse: emit Unknown
                let b = self.buf.clone();
                self.buf.clear();
                return Some(Key::Unknown(b));
            }
        }
    }
}

fn parse(b: &[u8]) -> Option<(Key, usize)> {
    if b.is_empty() {
        return None;
    }
    match b[0] {
        0x1b => {
            if b.len() == 1 {
                return Some((Key::Esc, 1));
            }
            match b[1] {
                b'[' => {
                    // CSI
                    let mut i = 2;
                    while i < b.len() && !(0x40..=0x7e).contains(&b[i]) {
                        i += 1;
                    }
                    if i >= b.len() {
                        return None;
                    }
                    let params = &b[2..i];
                    let fin = b[i];
                    let k = csi(params, fin);
                    return Some((k, i + 1));
                }
                b'O' => {
                    if b.len() < 3 {
                        return None;
                    }
                    let k = match b[2] {
                        b'A' => Key::Up,
                        b'B' => Key::Down,
                        b'C' => Key::Right,
                        b'D' => Key::Left,
                        b'H' => Key::Home,
                        b'F' => Key::End,
                        b'P' => Key::F(1),
                        b'Q' => Key::F(2),
                        b'R' => Key::F(3),
                        b'S' => Key::F(4),
                        _ => Key::Unknown(vec![0x1b, b'O', b[2]]),
                    };
                    return Some((k, 3));
                }
                0x1b => return Some((Key::Esc, 1)),
                _ => {
                    // Alt + key
                    let (k, used) = parse(&b[1..])?;
                    let k = match k {
                        Key::Char(c) => Key::AltChar(c),
                        Key::Up => Key::Alt(Key::Up),
                        Key::Down => Key::Alt(Key::Down),
                        Key::Left => Key::Alt(Key::Left),
                        Key::Right => Key::Alt(Key::Right),
                        other => Key::Alt(other),
                    };
                    return Some((k, used + 1));
                }
            }
        }
        b'\r' | b'\n' => Some((Key::Enter, 1)),
        b'\t' => Some((Key::Tab, 1)),
        0x7f => Some((Key::Backspace, 1)),
        0x08 => Some((Key::Ctrl('h'), 1)),
        0x00..=0x1a => Some((Key::Ctrl((b[0] + b'a' - 1) as char), 1)),
        0x1c..=0x1f => Some((Key::Ctrl((b[0] - 0x1c + b'\\') as char), 1)),
        _ => {
