            let len = utf8_len(b[0]);
            if len == 0 {
                return Some((Key::Unknown(vec![b[0]]), 1));
            }
            if b.len() < len {
                return None;
            }
            match std::str::from_utf8(&b[..len]) {
                Ok(s) => {
                    let c = s.chars().next().unwrap();
                    Some((Key::Char(c), len))
                }
                Err(_) => Some((Key::Unknown(vec![b[0]]), 1)),
            }
        }
    }
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if b >> 5 == 0b110 {
        2
    } else if b >> 4 == 0b1110 {
        3
    } else if b >> 3 == 0b11110 {
        4
    } else if b >> 2 == 0b111110 {
        5
    } else if b >> 1 == 0b1111110 {
        6
    } else {
        0
    }
}

fn csi(params: &[u8], fin: u8) -> Key {
    let s = String::from_utf8_lossy(params).to_string();
    let nums: Vec<u32> = s
        .split(';')
        .map(|x| x.parse::<u32>().unwrap_or(0))
        .collect();
    match fin {
        b'A' => Key::Up,
        b'B' => Key::Down,
        b'C' => Key::Right,
        b'D' => Key::Left,
        b'H' => Key::Home,
        b'F' => Key::End,
        b'Z' => Key::BackTab,
        b'~' => {
            let n = nums.first().copied().unwrap_or(0);
            match n {
                1 | 7 => Key::Home,
                2 => Key::Insert,
                3 => Key::Delete,
                4 | 8 => Key::End,
                5 => Key::PageUp,
                6 => Key::PageDown,
                11..=15 => Key::F((n - 10) as u8),
                17..=21 => Key::F((n - 11) as u8),
                23..=26 => Key::F((n - 12) as u8),
                _ => Key::Unknown(params.to_vec()),
            }
        }
        b'M' | b'm' => Key::Unknown(params.to_vec()),
        _ => Key::Unknown(params.to_vec()),
    }
}
