#[derive(Debug, Clone, PartialEq)]
pub enum Key {
    Char(char),
    Enter,
    Esc,
    Tab,
    BackTab,
    Backspace,
    Delete,
    Insert,
    Home,
    End,
    PageUp,
    PageDown,
    Up,
    Down,
    Left,
    Right,
    F(u8),
    Ctrl(char),
    Alt(Key),
    AltChar(char),
    Unknown(Vec<u8>),
}

pub struct Keys {
    buf: Vec<u8>,
}

impl Keys {
    pub fn new() -> Keys {
        Keys { buf: Vec::new() }
    }
    fn read_more(&mut self) -> bool {
        let mut b = [0u8; 1024];
        let n = unsafe { read(0, b.as_mut_ptr(), b.len()) };
        if n <= 0 {
            return false;
        }
        self.buf.extend_from_slice(&b[..n as usize]);
        true
    }
    pub fn next(&mut self) -> Option<Key> {
        loop {
            if self.buf.is_empty() {
                if !self.read_more() {
                    return None;
                }
            }
            if let Some((k, used)) = parse(&self.buf) {
                self.buf.drain(..used);
                return Some(k);
            }
            if !self.read_more() {
                if self.buf.is_empty() {
                    return None;
                }
                // can't parse: emit Unknown
                let b = self.buf.clone();
                self.buf.clear();
                return Some(Key::Unknown(b));
            }
        }
    }
}

fn parse(b: &[u8]) -> Option<(Key, usize)> {
    if b.is_empty() {
        return None;
    }
    match b[0] {
        0x1b => {
            if b.len() == 1 {
                return Some((Key::Esc, 1));
