                    let mut i = 2;
                    while i < b.len() && !(0x40..=0x7e).contains(&b[i]) {
                        i += 1;
                    }
                    if i >= b.len() {
                        return None;
                    }
                    let params = &b[2..i];
                    let fin = b[i];
                    let k = csi(params, fin);
                    return Some((k, i + 1));
                }
                b'O' => {
                    if b.len() < 3 {
                        return None;
                    }
                    let k = match b[2] {
                        b'A' => Key::Up,
                        b'B' => Key::Down,
                        b'C' => Key::Right,
                        b'D' => Key::Left,
                        b'H' => Key::Home,
                        b'F' => Key::End,
                        b'P' => Key::F(1),
                        b'Q' => Key::F(2),
                        b'R' => Key::F(3),
                        b'S' => Key::F(4),
                        _ => Key::Unknown(vec![0x1b, b'O', b[2]]),
                    };
                    return Some((k, 3));
                }
                0x1b => return Some((Key::Esc, 1)),
                _ => {
                    // Alt + key
                    let (k, used) = parse(&b[1..])?;
                    let k = match k {
                        Key::Char(c) => Key::AltChar(c),
                        Key::Up => Key::Alt(Key::Up),
                        Key::Down => Key::Alt(Key::Down),
                        Key::Left => Key::Alt(Key::Left),
                        Key::Right => Key::Alt(Key::Right),
                        other => Key::Alt(other),
                    };
                    return Some((k, used + 1));
                }
            }
        }
