use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

#[derive(Debug, Clone, PartialEq)]
pub enum Kind {
    Dir,
    File,
}

#[derive(Debug, Clone)]
pub struct Item {
    pub name: String,
    pub path: PathBuf,
    pub is_dir: bool,
    pub is_symlink: bool,
    pub size: u64,
    pub modified: SystemTime,
    pub perm: u32,
    pub target: Option<PathBuf>,
}

impl Item {
    pub fn ext(&self) -> String {
        let n = &self.name;
        if n.starts_with('.') {
            return String::new();
        }
        match n.rfind('.') {
            Some(i) if i + 1 < n.len() => n[i + 1..].to_lowercase(),
            _ => String::new(),
        }
    }
}

pub fn size_str(len: u64) -> String {
    if len < 1000 {
        format!("{}B", len)
    } else if len < 1000 * 1000 {
        format!("{}KB", len / 1000)
    } else if len < 1000 * 1000 * 1000 {
        format!("{}MB", len / 1000 / 1000)
    } else {
        format!("{}GB", len / 1000 / 1000 / 1000)
    }
}

fn is_dir_like(p: &Path) -> bool {
    match fs::metadata(p) {
        Ok(m) => m.is_dir(),
        Err(_) => false,
    }
}

/// List items in directory `dir`. Returns items sorted.
pub fn list_dir(dir: &Path, show_hidden: bool, sort_by_name: bool) -> Vec<Item> {
    let rd = match fs::read_dir(dir) {
        Ok(r) => r,
        Err(_) => return Vec::new(),
    };
    let mut items: Vec<Item> = Vec::new();
    for e in rd {
        let e = match e {
            Ok(e) => e,
            Err(_) => continue,
        };
        let name = e.file_name().to_string_lossy().into_owned();
        if !show_hidden && name.starts_with('.') {
            continue;
        }
        let path = e.path();
        let link = fs::symlink_metadata(&path).ok();
        let is_symlink = link.as_ref().map(|m| m.file_type().is_symlink()).unwrap_or(false);
        let meta = if is_symlink {
            fs::metadata(&path).ok()
        } else {
            link.clone().map(|m| m)
        };
        let (is_dir, size, modified, perm) = match &meta {
            Some(m) => (m.is_dir(), m.len(), m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.mode() & 0o777),
            None => match &link {
                Some(m) => (
                    false,
                    m.len(),
                    m.modified().unwrap_or(SystemTime::UNIX_EPOCH),
                    m.mode() & 0o777,
                ),
                None => (false, 0, SystemTime::UNIX_EPOCH, 0),
            },
        };
        let target = if is_symlink { fs::read_link(&path).ok() } else { None };
        items.push(Item {
            name,
            path,
            is_dir,
            is_symlink,
            size,
            modified,
            perm,
            target,
        });
    }
    // stable sort: dirs first, then by name (natural, case-insensitive) or time desc
    if sort_by_name {
        items.sort_by(|a, b| {
            match (a.is_dir, b.is_dir) {
                (true, false) => std::cmp::Ordering::Less,
                (false, true) => std::cmp::Ordering::Greater,
                _ => natcmp(&a.name.to_lowercase(), &b.name.to_lowercase()),
            }
        });
    } else {
        items.sort_by(|a, b| {
            match (a.is_dir, b.is_dir) {
                (true, false) => std::cmp::Ordering::Less,
                (false, true) => std::cmp::Ordering::Greater,
                _ => b.modified.cmp(&a.modified),
            }
        });
    }
    items
}

fn canonical(s: &[u8]) -> bool {
    if s.is_empty() {
        return false;
    }
    if s.len() == 1 {
        return true;
    }
    s[0] != b'0'
}

fn cmp_run(a: &[u8], b: &[u8]) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    if canonical(a) && canonical(b) {
        let ta: &[u8] = if a[0] == b'0' { &a[1..] } else { a };
        let tb: &[u8] = if b[0] == b'0' { &b[1..] } else { b };
        match ta.len().cmp(&tb.len()) {
            Ordering::Equal => {}
            o => return o,
        }
        return ta.cmp(tb);
    }
    a.cmp(b)
}

pub fn natcmp(x: &str, y: &str) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    let (ab, bb) = (x.as_bytes(), y.as_bytes());
    let (mut i, mut j) = (0usize, 0usize);
    while i < ab.len() && j < bb.len() {
        let (ca, cb) = (ab[i], bb[j]);
        if ca.is_ascii_digit() && cb.is_ascii_digit() {
            let mut i2 = i;
            while i2 < ab.len() && ab[i2].is_ascii_digit() {
                i2 += 1;
            }
            let mut j2 = j;
            while j2 < bb.len() && bb[j2].is_ascii_digit() {
                j2 += 1;
            }
            let o = cmp_run(&ab[i..i2], &bb[j..j2]);
            if o != Ordering::Equal {
                return o;
            }
            i = i2;
            j = j2;
        } else if ca != cb {
            return ca.cmp(&cb);
        } else {
            i += 1;
            j += 1;
        }
    }
    (ab.len() - i).cmp(&(bb.len() - j))
}

/// preview text lines for an item
pub fn preview_lines(item: &Item) -> Vec<String> {
    if item.is_dir {
        if let Ok(rd) = fs::read_dir(&item.path) {
            let mut names: Vec<(bool, String)> = Vec::new();
            for e in rd.flatten() {
                let n = e.file_name().to_string_lossy().into_owned();
                let d = e.path().is_dir();
                names.push((d, n));
            }
            names.sort_by(|a, b| match (a.0, b.0) {
                (true, false) => std::cmp::Ordering::Less,
                (false, true) => std::cmp::Ordering::Greater,
                _ => natcmp(&a.1.to_lowercase(), &b.1.to_lowercase()),
            });
            let n = names.len();
            let mut out = Vec::new();
            for (i, (_, nm)) in names.iter().enumerate() {
                let c = if i + 1 == n { '└' } else { '├' };
                out.push(format!("{} {}", c, nm));
            }
            return out;
        }
        return vec!["(file not readable)".to_string()];
    }
    let bytes = match fs::read(&item.path) {
        Ok(b) => b,
        Err(_) => return vec!["(file not readable)".to_string()],
    };
    let s = match String::from_utf8(bytes) {
        Ok(s) => s,
        Err(_) => return Vec::new(),
    };
    if s.contains('\0') {
        return vec!["(binary file)".to_string()];
    }
    let mut out = Vec::new();
    for line in s.split('\n') {
        let line = line.trim_end_matches('\r');
        let mut cur = String::new();
        for ch in line.chars() {
            if ch == '\t' {
                cur.push_str("    ");
            } else if (ch as u32) < 32 || ch as u32 == 127 {
                // control char: skip
            } else {
                cur.push(ch);
            }
        }
        out.push(cur);
    }
    out
}
RSEOF
echo ok"}

