pub const TITLE_FG: u8 = 6;
pub const PREVIEW_FG: u8 = 8;

pub struct Colors {
    pub dir_fg: u8,
    pub file_fg: u8,
    pub symlink_fg: u8,
    pub dirty_fg: u8,
}

