        Colors { dir_fg: 14, file_fg: 15, symlink_fg: 11, dirty_fg: 8 }
    }
}

pub fn fg(n: u8) -> String {
    format!("\x1b[38;5;{}m", n)
}

pub fn move_to(x: i32, y: i32) -> String {
    let x = if x < 0 { 0 } else { x };
    let y = if y < 0 { 0 } else { y };
    format!("\x1b[{};{}H", y + 1, x + 1)
}

pub struct Layout {
    pub w: i32,
    pub h: i32,
    pub rows: i32,       // item rows
    pub left_w: i32,     // width of the left pane (W or W/2)
    pub right: bool,     // whether a right pane exists (vertical split / register)
    pub right_x: i32,    // right pane x
    pub right_w: i32,
    pub date_col: i32,   // -1 if not shown
    pub name_max: i32,
    pub status_w: i32,
    pub status_row: i32,
    pub horiz: bool,
}

impl Layout {
    pub fn new(w: i32, h: i32, right: bool, horiz: bool) -> Layout {
        let rows = (h - 3).max(0);
        let left_w = if right { w / 2 } else { w };
        let right_x = if right { left_w + 1 } else { w };
        let right_w = (w - right_x).max(0);
        let date_col = if left_w >= 28 { left_w - 17 } else { -1 };
        let name_max = if date_col >= 0 { date_col - 2 } else { left_w - 2 };
        let status_w = if right { left_w } else { w };
        let status_row = if horiz { h / 2 - 1 } else { h - 1 };
        Layout { w, h, rows, left_w, right, right_x, right_w, date_col, name_max, status_w, status_row, horiz }
    }
}

pub fn truncate_name(s: &str, max: i32) -> String {
    let max = max.max(0) as usize;
    let chars: Vec<char> = s.chars().collect();
    if chars.len() <= max {
        return s.to_string();
    }
    if max < 2 {
        return chars[..max].iter().collect();
    }
    let mut out: String = chars[..max - 2].iter().collect();
    out.push('.');
    out.push('.');
    out
}

/// state needed for drawing
pub struct DrawState<'a> {
    pub path: &'a str,
    pub items: &'a [Item],
    pub cursor: usize,
    pub offset: usize,
    pub colors: &'a Colors,
    pub search: Option<&'a str>,
    pub visual: Option<(usize, usize)>,
    pub show_reg: bool,
    pub registers: &'a [(String, Vec<String>)],
    pub preview: bool,
    pub split_horiz: bool,
    pub preview_scroll: usize,
    pub preview_title: String,
    pub preview_lines: Vec<String>,
    pub message: Option<&'a str>,
    pub layout: Layout,
}

pub fn date_str(t: &std::time::SystemTime) -> String {
    let secs = t.duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
    let (y, mo, d, h, mi) = civil(secs as i64);
    format!("{:04}-{:02}-{:02} {:02}:{:02}", y, mo, d, h, mi)
}

fn civil(secs: i64) -> (i64, u32, u32, u32, u32) {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let h = (rem / 3600) as u32;
    let mi = ((rem % 3600) / 60) as u32;
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as i64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d, h, mi)
}

pub fn item_fg(item: &Item, c: &Colors) -> u8 {
    if item.is_symlink {
        c.symlink_fg
    } else if item.is_dir {
        c.dir_fg
    } else {
        c.file_fg
    }
}

/// status line text (without the leading space)
pub fn status_text(item: Option<&Item>, idx: usize, len: usize) -> String {
    let mut s = format!(" {}/{}", idx + 1, len);
    match item {
        None => {}
        Some(it) => {
            if it.is_symlink {
                match &it.target {
                    Some(t) => s.push_str(&format!(" linked to: {}", t.display())),
                    None => s.push_str(" linked to: (invalid path)"),
                }
            } else {
                if !it.is_dir {
                    let e = it.ext();
                    if it.name.contains('.') && !it.name.starts_with('.') {
                        s.push(' ');
                        s.push_str(&e);
                    }
                }
                s.push(' ');
                s.push_str(&size_str(it.size));
                s.push(' ');
                s.push_str(&format!("{:o}", it.perm));
            }
        }
    }
    s
}
RSEOF
echo ok"}

{"command": "cat > src/app.rs <<'RSEOF'
use crate::draw::*;
use crate::list::{list_dir, preview_lines, Item};
use crate::term::{Key, Term};
use std::path::{Path, PathBuf};
use std::time::Instant;

#[derive(Clone, PartialEq)]
pub enum Split {
    Vertical,
    Horizontal,
}

#[derive(Clone, PartialEq)]
pub enum InputKind {
    NewFile,
    NewDir,
    Rename,
    Zoxide,
}

#[derive(Clone, PartialEq)]
pub enum Mode {
    Normal,
    Search { input: String },
    Command { input: String },
    Input { kind: InputKind, input: String },
    Visual { start: usize },
}

pub struct App {
    pub term: Term,
    pub cwd: PathBuf,
    pub items: Vec<Item>,
    pub cursor: usize,
    pub offset: usize,
    pub show_hidden: bool,
    pub preview: bool,
    pub split: Split,
    pub sort_by_name: bool,
    pub colors: Colors,
    pub mode: Mode,
    pub show_reg: bool,
    pub registers: Vec<(String, Vec<String>)>,
    pub search_word: String,
    pub preview_scroll: usize,
    pub message: Option<String>,
    pub pending: Option<char>,
    pub visual_anchor: Option<usize>,
    pub history: Vec<PathBuf>,
    pub hist_pos: usize,
    pub undo: Vec<crate::ops::Op>,
    pub redo: Vec<crate::ops::Op>,
    pub yank: Vec<PathBuf>,
    pub trash_dir: PathBuf,
    pub log: bool,
    pub quit_with_cd: bool,
    pub layout: Layout,
    pub need_full: bool,
    pub w: i32,
    pub h: i32,
}

impl App {
    pub fn new(mut term: Term, cwd: PathBuf, log: bool) -> App {
        let (w, h) = term.size().unwrap_or((80, 24));
        let cfg = crate::config::load();
        let items = list_dir(&cwd, cfg.show_hidden, true);
        let mut a = App {
            term,
            cwd,
            items,
            cursor: 0,
            offset: 0,
            show_hidden: cfg.show_hidden,
            preview: false,
            split: Split::Vertical,
            sort_by_name: true,
            colors: cfg.colors,
            mode: Mode::Normal,
            show_reg: false,
            registers: Vec::new(),
            search_word: String::new(),
            preview_scroll: 0,
            message: None,
            pending: None,
            visual_anchor: None,
            history: Vec::new(),
            hist_pos: 0,
            undo: Vec::new(),
            redo: Vec::new(),
            yank: Vec::new(),
            trash_dir: crate::ops::trash_dir(),
            log,
            quit_with_cd: false,
            layout: Layout::new(w as i32, h as i32, false, false),
            need_full: true,
            w: w as i32,
            h: h as i32,
        };
        crate::ops::load_session(&mut a);
        a.reload();
        a.layout = a.compute_layout();
        a
    }

    pub fn compute_layout(&self) -> Layout {
        let horiz = self.preview && self.split == Split::Horizontal;
        let right = (self.preview && self.split == Split::Vertical) || self.show_reg;
        Layout::new(self.w, self.h, right, horiz)
    }

    pub fn reload(&mut self) {
        self.items = list_dir(&self.cwd, self.show_hidden, self.sort_by_name);
        if self.cursor >= self.items.len() {
            self.cursor = self.items.len().saturating_sub(1);
        }
        self.fix_offset();
    }

    pub fn fix_offset(&mut self) {
        let limit = (self.layout.rows - 4).max(0) as usize;
        if self.cursor > self.offset + limit {
            self.offset = self.cursor - limit;
        }
        if self.cursor < self.offset {
            self.offset = self.cursor;
        }
        let max_off = self.items.len().saturating_sub(1);
        if self.offset > max_off {
            self.offset = max_off;
        }
    }

    pub fn push_history(&mut self) {
        let cur = self.cwd.clone();
        if self.history.last() != Some(&cur) {
            self.history.push(cur);
            self.hist_pos = self.history.len() - 1;
        }
    }

    // ---------------- drawing ----------------

    pub fn out(&mut self, s: &str) {
        self.term.write(s.as_bytes());
    }

    pub fn draw(&mut self) {
        self.layout = self.compute_layout();
        let l = self.layout;
        if self.need_full {
            self.out("\x1b[2J");
            self.draw_title();
            self.draw_items();
        }
        self.out(" \x1b[1D");
        if self.message.is_some() {
            self.draw_message();
        } else {
            self.draw_status();
        }
        if self.show_reg {
            self.draw_reg();
        } else if self.preview {
            self.draw_preview();
        }
        self.draw_marker();
        self.need_full = false;
    }

    fn draw_title(&mut self) {
        let p = format!(" {}", self.cwd.display());
        self.out(&move_to(0, 0));
        self.out(&fg(TITLE_FG));
        self.out(&p);
        self.out("\x1b[0m");
        if self.layout.right {
            let name = self.preview_title_name();
            let max = (self.layout.w - self.layout.w / 2 - 1).max(0) as usize;
            let t: String = {
                let s = format!("[{}]", name);
                s.chars().take(max).collect()
            };
            self.out(&move_to(self.layout.w / 2, 0));
            self.out("\x1b[K");
            self.out("\x1b[1C");
            self.out(&t);
        }
    }

    pub fn preview_title_name(&self) -> String {
        match self.items.get(self.cursor) {
            Some(it) => it.name.clone(),
            None => String::new(),
        }
    }

    fn draw_items(&mut self) {
        let l = self.layout;
        let search = match &self.mode {
            Mode::Search { input } => Some(input.clone()),
            _ => None,
        };
        let n = self.items.len();
        let vis_end = (self.offset as i32 + l.rows).min(n as i32);
        let mut i = self.offset as i32;
        while i < vis_end {
            let it = &self.items[i as usize];
            let row = 2 + (i - self.offset as i32);
            let fgc = item_fg(it, &self.colors);
            let selected = match self.mode {
                Mode::Visual { start } => {
                    let (a, b) = if start <= self.cursor { (start, self.cursor) } else { (self.cursor, start) };
                    let idx = i as usize;
                    idx >= a && idx <= b
                }
                _ => false,
            };
            let matched = match &search {
                Some(w) => !w.is_empty() && it.name.contains(w.as_str()),
                None => false,
            };
            let disp = truncate_name(&it.name, l.name_max);
            self.out(&move_to(2, row));
            self.out(&fg(fgc));
            if matched {
                self.out("\x1b[1m");
            }
            if selected {
                self.out("\x1b[7m");
            }
            self.out(&disp);
            if matched || selected {
                self.out("\x1b[0m");
            }
            if l.date_col >= 0 {
                self.out("\x1b[1000D");
                self.out(&format!("\x1b[{}C", l.date_col));
                if matched {
                    self.out(&fg(fgc));
                }
                self.out(" ");
                if selected {
                    self.out("\x1b[7m");
                }
                self.out(&date_str(&it.modified));
                if selected {
                    self.out("\x1b[0m");
                }
            }
            self.out("\x1b[0m");
            i += 1;
        }
    }

    fn draw_status(&mut self) {
        let l = self.layout;
        self.out(&move_to(0, l.status_row));
        self.out("\x1b[2K");
        self.out("\x1b[0m");
        self.out("\x1b[7m");
        self.out(&" ".repeat(l.status_w.max(0) as usize));
        self.out("\x1b[0m");
        self.out(&move_to(0, l.status_row));
        if let Mode::Search { input } = &self.mode {
            let count = self.count_matches(input);
            let cs = if count == 1 { "1 match".to_string() } else { format!("{} matches", count) };
            for seg in [" ", "/", input.as_str(), " - ", cs.as_str()] {
                self.out("\x1b[7m");
                self.out(seg);
                self.out("\x1b[0m");
            }
        } else {
            let it = self.items.get(self.cursor);
            let txt = status_text(it, self.cursor, self.items.len());
            self.out("\x1b[7m");
            self.out(&txt);
            self.out("\x1b[0m");
        }
    }

    fn count_matches(&self, w: &str) -> usize {
        self.items.iter().filter(|i| i.name.contains(w)).count()
    }

    fn draw_message(&mut self) {
        let m = self.message.clone().unwrap_or_default();
        self.out(&move_to(1, 1));
        self.out("\x1b[2K");
        self.out(&m);
    }

    fn draw_reg(&mut self) {
        let l = self.layout;
        let clear_rows = l.rows + 4;
        for r in 0..clear_rows {
            self.out(&move_to(l.right_x, 2 + r));
            self.out("\x1b[K");
        }
        for (i, (name, vals)) in self.registers.iter().enumerate() {
            if (i as i32) >= l.rows {
                break;
            }
            let joined = if vals.is_empty() { String::new() } else { vals.join(" ") };
            self.out(&move_to(l.right_x, 2 + i as i32));
            self.out(&format!("\"{} {}", name, joined));
        }
    }

    fn draw_preview(&mut self) {
        let l = self.layout;
        let (first_row, count, width) = if l.horiz {
            (self.h / 2 + 1, (self.h - self.h / 2 - 2).max(0), self.w)
        } else {
            (2, (self.h - 3).max(0), l.right_w)
        };
        let clear_count = if l.horiz { count + 3 } else { count + 4 };
        for r in 0..clear_count {
            self.out(&move_to(if l.horiz { 0 } else { l.right_x }, first_row + r));
            self.out("\x1b[K");
        }
        self.out(&move_to(if l.horiz { 0 } else { l.right_x }, first_row));
        let mut lines: Vec<String> = Vec::new();
        for raw in self.preview_lines.iter() {
            let chars: Vec<char> = raw.chars().collect();
            if chars.is_empty() {
                lines.push(String::new());
            } else {
                let wch = width.max(1) as usize;
                for chunk in chars.chunks(wch) {
                    lines.push(chunk.iter().collect());
                }
            }
        }
        let total = lines.len();
        let sc = self.preview_scroll.min(total.saturating_sub(1));
        let mut i = sc;
        let mut shown = 0;
        while i < total && shown < count {
            let row = first_row + shown;
            self.out(&move_to(if l.horiz { 0 } else { l.right_x }, row));
            self.out(&fg(PREVIEW_FG));
            self.out(&lines[i]);
            i += 1;
            shown += 1;
        }
        self.out("\x1b[0m");
    }

    fn draw_marker(&mut self) {
        let row = 2 + (self.cursor as i32 - self.offset as i32);
        self.out(&move_to(0, row));
        self.out(">");
        self.out("\x1b[1D");
    }

    pub fn flush(&mut self) {
        self.term.flush();
    }

    pub fn show_msg(&mut self, m: &str) {
        self.message = Some(m.to_string());
    }

    pub fn refresh_preview(&mut self) {
        if self.show_reg {
            self.preview_lines.clear();
            return;
        }
        match self.items.get(self.cursor) {
            Some(it) => {
                self.preview_lines = preview_lines(it);
            }
            None => self.preview_lines.clear(),
        }
    }
}
RSEOF
echo ok"}

