use crate::app::{App, Mode};
use crate::list::Item;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Debug)]
pub enum Op {
    Put { paths: Vec<PathBuf> },
    Delete { paths: Vec<PathBuf>, trash: Vec<PathBuf> },
    Rename { from: Vec<PathBuf>, to: Vec<PathBuf> },
}

pub fn data_dir() -> PathBuf {
    if let Ok(x) = std::env::var("XDG_DATA_HOME") {
        if !x.is_empty() {
            return PathBuf::from(x).join("felix");
        }
    }
    let home = std::env::var("HOME").unwrap_or_else(|_| "/".to_string());
    PathBuf::from(home).join(".local/share/felix")
}

pub fn config_dir() -> PathBuf {
    if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
        if !x.is_empty() {
            return PathBuf::from(x).join("felix");
        }
    }
    let home = std::env::var("HOME").unwrap_or_else(|_| "/".to_string());
    PathBuf::from(home).join(".config/felix")
}

pub fn trash_dir() -> PathBuf {
    data_dir().join("Trash")
}

pub fn log_dir() -> PathBuf {
    data_dir().join("log")
}

pub fn runtime_dir() -> Option<PathBuf> {
    if let Ok(x) = std::env::var("XDG_RUNTIME_DIR") {
        if !x.is_empty() {
            return Some(PathBuf::from(x).join("felix"));
        }
    }
    if let Ok(x) = std::env::var("TMPDIR") {
        if !x.is_empty() {
            return Some(PathBuf::from(x).join("felix"));
        }
    }
    Some(PathBuf::from("/tmp/felix"))
}

pub fn now_secs() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0)
}

pub fn ensure_dirs() {
    let _ = std::fs::create_dir_all(trash_dir());
    let _ = std::fs::create_dir_all(config_dir());
}

// ---------------- session ----------------

#[derive(PartialEq, Clone, Copy)]
pub enum SortBy {
    Name,
    Time,
}

pub fn load_session(a: &mut App) {
    let p = data_dir().join(".session");
    if let Ok(s) = std::fs::read_to_string(&p) {
        let mut sort_name = true;
        let mut hidden = true;
        let mut preview = false;
        let mut vertical = true;
        for line in s.lines() {
            let mut it = line.splitn(2, ':');
            let k = it.next().unwrap_or("").trim();
            let v = it.next().unwrap_or("").trim();
            match k {
                "sort_by" => sort_name = v == "Name",
                "show_hidden" => hidden = v == "true",
                "preview" => preview = v == "true",
                "split" => vertical = v == "Vertical",
                _ => {}
            }
        }
        a.sort_by_name = sort_name;
        a.show_hidden = hidden;
        a.preview = preview;
        a.split = if vertical { crate::app::Split::Vertical } else { crate::app::Split::Horizontal };
    }
}

pub fn save_session(a: &App) {
    let d = data_dir();
    let _ = std::fs::create_dir_all(&d);
    let s = format!(
        "sort_by: {}\nshow_hidden: {}\npreview: {}\nsplit: {}\n",
        if a.sort_by_name { "Name" } else { "Time" },
        a.show_hidden,
        a.preview,
        if a.split == crate::app::Split::Vertical { "Vertical" } else { "Horizontal" }
    );
    let _ = std::fs::write(d.join(".session"), s);
}

// ---------------- logging ----------------

pub struct Logger {
    file: Option<std::fs::File>,
}

impl Logger {
    pub fn new() -> Logger {
        Logger { file: None }
    }
    pub fn start(&mut self) {
        let d = log_dir();
        let _ = std::fs::create_dir_all(&d);
        let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|x| x.as_secs()).unwrap_or(0);
        let (y, mo, dd, h, mi, se) = civil6(now as i64);
        let name = format!("{:04}-{:02}-{:02}-{:02}-{:02}-{:02}.log", y, mo, dd, h, mi, se);
        if let Ok(f) = std::fs::OpenOptions::new().create(true).append(true).write(true).open(d.join(name)) {
            self.file = Some(f);
            self.info("===START===");
        }
    }
    fn write(&mut self, level: &str, msg: &str) {
        use std::io::Write;
        if let Some(f) = self.file.as_mut() {
            let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|x| x.as_secs()).unwrap_or(0);
            let (_, _, _, h, mi, se) = civil6(now as i64);
            let _ = writeln!(f, "{:02}:{:02}:{:02} [{}] {}", h, mi, se, level, msg);
            let _ = f.flush();
        }
    }
    pub fn info(&mut self, msg: &str) {
        self.write("INFO", msg);
    }
    pub fn warn(&mut self, msg: &str) {
        self.write("WARN", msg);
    }
}

pub fn civil6(secs: i64) -> (i64, u32, u32, u32, u32, u32) {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let h = (rem / 3600) as u32;
    let mi = ((rem % 3600) / 60) as u32;
    let se = (rem % 60) as u32;
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as i64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d, h, mi, se)
}

// ---------------- operations ----------------

fn err_str(e: std::io::Error) -> String {
    format!("{}", e)
}

fn plural(n: usize, one: &str, many: &str) -> String {
    if n == 1 {
        format!("1 {}", one)
    } else {
        format!("{} {}", n, many)
    }
}

pub fn do_delete(a: &mut App, paths: Vec<PathBuf>) {
    if paths.is_empty() {
        return;
    }
    a.message = Some("DELETE: Processing...".to_string());
    a.draw();
    a.flush();
    let t = crate::ops::now_secs();
    let mut trash_paths = Vec::new();
    for p in &paths {
        let name = p.file_name().map(|x| x.to_string_lossy().into_owned()).unwrap_or_default();
        let tp = trash_dir().join(format!("{}_{}", t, name));
        let r = std::fs::rename(p, &tp);
        match r {
            Ok(_) => trash_paths.push(tp),
            Err(e) => {
                a.message = Some(err_str(e));
            }
        }
    }
    if a.log {
        let names: Vec<String> = paths.iter().map(|p| format!("\"{}\"", p.display())).collect();
        crate::LOGGER.info(&format!("DELETE: [{}]", names.join(", ")));
    }
    // undo bookkeeping
    let op = Op::Delete { paths: paths.clone(), trash: trash_paths.clone() };
    a.undo.push(op);
    a.redo.clear();
    a.reload();
    let n = trash_paths.len();
    let el = elapsed_str();
    let msg = if n == 1 {
        format!("1 item deleted. [{}]", el)
    } else {
        format!("{} items deleted [{}]", n, el)
    };
    if a.log {
        crate::LOGGER.info(&msg);
    }
    a.message = Some(msg);
    a.need_full = true;
    a.draw();
    a.flush();
}

pub fn do_put(a: &mut App, regs: &[(String, Vec<String>)], key: &str) {
    let cwd = a.cwd.clone();
    let mut src: Vec<PathBuf> = Vec::new();
    let mut names: Vec<String> = Vec::new();
    if key.is_empty() {
        // register zero
        if let Some((_, v)) = regs.iter().find(|(k, _)| k == "0") {
            for n in v {
                names.push(n.clone());
            }
        }
    } else {
        if let Some((_, v)) = regs.iter().find(|(k, _)| k == key) {
            for n in v {
                names.push(n.clone());
            }
        }
    }
    for n in &names {
        // find in trash
        let mut found = None;
        if let Ok(rd) = std::fs::read_dir(trash_dir()) {
            let mut v: Vec<PathBuf> = Vec::new();
            for e in rd.flatten() {
                v.push(e.path());
            }
            v.sort_by(|x, y| {
                let a = x.file_name().unwrap_or_default().to_string_lossy().to_string();
                let b = y.file_name().unwrap_or_default().to_string_lossy().to_string();
                b.cmp(&a)
            });
            for p in v {
                let f = p.file_name().unwrap_or_default().to_string_lossy().to_string();
                if let Some(rest) = f.strip_prefix(&format!("{}_", "0")) {
                    let _ = rest;
                }
                if let Some(idx) = f.find('_') {
                    if f[idx + 1..] == *n {
                        found = Some(p);
                        break;
                    }
                    // exact register-0 semantics: newest entry matching name
                    if key.is_empty() {
                        found = Some(p);
                        break;
                    }
                }
            }
        }
        if let Some(srcp) = found {
            let mut dst = cwd.join(n);
            let mut i = 1;
            while dst.exists() {
                let stem = stem_of(n);
                let ext = ext_of(n);
                dst = cwd.join(format!("{}_{}.{}", stem, i, ext));
                i += 1;
                if i > 1000 {
                    break;
                }
            }
            let r = copy_recursive(&srcp, &dst);
            match r {
                Ok(_) => {
                    src.push(dst);
                }
                Err(e) => {
                    a.message = Some(err_str(e));
                }
            }
        } else {
            a.message = Some("The item does not exist.".to_string());
        }
    }
    let n = src.len();
    if n > 0 {
        let op = Op::Put { paths: src.clone() };
        a.undo.push(op);
        a.redo.clear();
    }
    a.reload();
    let el = elapsed_str();
    let msg = if n == 1 {
        format!("1 item inserted. [{}]", el)
    } else {
        format!("{} items inserted. [{}]", n, el)
    };
    if a.log && n > 0 {
        let names: Vec<String> = src.iter().map(|p| format!("\"{}\"", p.display())).collect();
        crate::LOGGER.info(&format!("PUT: [{}]", names.join(", ")));
        crate::LOGGER.info(&msg);
    }
    a.message = Some(msg);
    a.need_full = true;
}

pub fn stem_of(n: &str) -> String {
    match n.rfind('.') {
        Some(i) if i > 0 => n[..i].to_string(),
        _ => n.to_string(),
    }
}
pub fn ext_of(n: &str) -> String {
    match n.rfind('.') {
        Some(i) if i + 1 < n.len() => n[i + 1..].to_string(),
        _ => String::new(),
    }
}

pub fn elapsed_str() -> String {
    let d = START.elapsed();
    format!("{:.2}s", d.as_secs_f64())
}

pub fn copy_recursive(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = std::fs::symlink_metadata(src)?;
    if meta.file_type().is_symlink() {
        let t = std::fs::read_link(src)?;
        return std::os::unix::fs::symlink(t, dst);
    }
    if meta.is_dir() {
        std::fs::create_dir(dst)?;
        for e in std::fs::read_dir(src)? {
            let e = e?;
            copy_recursive(&e.path(), &dst.join(e.file_name()))?;
        }
        Ok(())
    } else {
        std::fs::copy(src, dst)?;
        Ok(())
    }
}

pub fn undo_op(a: &mut App) {
    if a.undo.is_empty() {
        a.message = Some("No operations left.".to_string());
        return;
    }
    let op = a.undo.pop().unwrap();
    match op {
        Op::Put { paths } => {
            for p in &paths {
                let r = if p.is_dir() { std::fs::remove_dir_all(p) } else { std::fs::remove_file(p) };
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("UNDONE: PUT".to_string());
            a.redo.push(Op::Put { paths });
        }
        Op::Delete { paths, trash } => {
            for (p, t) in paths.iter().zip(trash.iter()) {
                let r = std::fs::copy(t, p);
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("UNDONE: DELETE".to_string());
            a.redo.push(Op::Delete { paths, trash });
        }
        Op::Rename { from, to } => {
            for (f, t) in from.iter().zip(to.iter()) {
                let r = std::fs::rename(t, f);
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("UNDONE: RENAME".to_string());
            a.redo.push(Op::Rename { from, to });
        }
    }
    if a.log {
        crate::LOGGER.info("UNDONE");
    }
    a.reload();
    a.need_full = true;
}

pub fn redo_op(a: &mut App) {
    if a.redo.is_empty() {
        a.message = Some("No operations left.".to_string());
        return;
    }
    let op = a.redo.pop().unwrap();
    match op {
        Op::Put { paths } => {
            // need source from trash: we stored destinations only; re-copy from trash by name
            for p in &paths {
                let name = p.file_name().unwrap_or_default().to_string_lossy().to_string();
                if let Some(t) = find_trash_by_name(&name) {
                    let _ = copy_recursive(&t, p);
                }
            }
            a.message = Some("REDONE: PUT".to_string());
            a.undo.push(Op::Put { paths });
        }
        Op::Delete { paths, trash } => {
            for p in &paths {
                let r = if p.is_dir() { std::fs::remove_dir_all(p) } else { std::fs::remove_file(p) };
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("REDONE DELETE".to_string());
            a.undo.push(Op::Delete { paths, trash });
        }
        Op::Rename { from, to } => {
            for (f, t) in from.iter().zip(to.iter()) {
                let r = std::fs::rename(f, t);
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("REDONE: RENAME".to_string());
            a.undo.push(Op::Rename { from, to });
        }
    }
    a.reload();
    a.need_full = true;
}

pub fn find_trash_by_name(name: &str) -> Option<PathBuf> {
    let mut best: Option<(u64, PathBuf)> = None;
    if let Ok(rd) = std::fs::read_dir(trash_dir()) {
        for e in rd.flatten() {
            let f = e.file_name().to_string_lossy().to_string();
            if let Some(idx) = f.find('_') {
                if &f[idx + 1..] == name {
                    if let Ok(n) = f[..idx].parse::<u64>() {
                        if best.as_ref().map(|(b, _)| n > *b).unwrap_or(true) {
                            best = Some((n, e.path()));
                        }
                    }
                }
            }
        }
    }
    best.map(|(_, p)| p)
}

pub fn do_create(a: &mut App, name: &str, is_dir: bool) {
    let p = a.cwd.join(name);
    let r = if is_dir { std::fs::create_dir(&p) } else { std::fs::File::create(&p).map(|_| ()) };
    match r {
        Ok(_) => {
            a.reload();
            if let Some(i) = a.items.iter().position(|x| x.name == name) {
                a.cursor = i;
            }
            a.fix_offset();
            a.need_full = true;
        }
        Err(e) => {
            a.message = Some(err_str(e));
        }
    }
}

pub fn do_rename(a: &mut App, from: PathBuf, new: &str) {
    let to = a.cwd.join(new);
    if from == to {
        let op = Op::Rename { from: vec![from.clone()], to: vec![to.clone()] };
        a.undo.push(op);
        a.redo.clear();
        return;
    }
    match std::fs::rename(&from, &to) {
        Ok(_) => {
            let op = Op::Rename { from: vec![from], to: vec![to] };
            a.undo.push(op);
            a.redo.clear();
            a.reload();
            a.need_full = true;
        }
        Err(e) => {
            a.message = Some(err_str(e));
            a.reload();
            a.need_full = true;
        }
    }
}

pub fn empty_trash(a: &mut App) {
    let r = std::fs::read_dir(trash_dir());
    let mut n = 0;
    if let Ok(rd) = r {
        for e in rd.flatten() {
            let p = e.path();
            let rr = if p.is_dir() { std::fs::remove_dir_all(&p) } else { std::fs::remove_file(&p) };
            if rr.is_ok() {
                n += 1;
            }
        }
    }
    a.message = Some(format!("Deleted {} items from the trash directory.", n));
}

pub fn yank(a: &mut App, names: Vec<String>, reg: Option<char>, append: bool) {
    // store into registers
    set_register(a, reg, names.clone(), append);
    let n = names.len();
    let msg = if n == 1 { "1 item yanked.".to_string() } else { format!("{} items yanked", n) };
    a.message = Some(msg);
}

pub fn set_register(a: &mut App, reg: Option<char>, names: Vec<String>, append: bool) {
    let key = match reg {
        Some(c) => c.to_string(),
        None => "0".to_string(),
    };
    if let Some(e) = a.registers.iter_mut().find(|(k, _)| *k == key) {
        if append {
            e.1.extend(names);
        } else {
            e.1 = names;
        }
    } else {
        a.registers.push((key, names));
    }
    // unnamed register
    if let Some(e) = a.registers.iter_mut().find(|(k, _)| k.is_empty()) {
        if append {
            e.1.extend(names);
        } else {
            e.1 = names;
        }
    } else {
        let mut v = names;
        let e = (String::new(), std::mem::take(&mut v));
        a.registers.insert(0, e);
    }
}

pub fn get_register(regs: &[(String, Vec<String>)], key: &str) -> Vec<String> {
    if let Some((_, v)) = regs.iter().find(|(k, _)| k == key) {
        v.clone()
    } else {
        Vec::new()
    }
}

pub fn delete_and_yank(a: &mut App, names: Vec<String>, reg: Option<char>, append: bool) {
    set_register(a, reg, names.clone(), append);
    let cwd = a.cwd.clone();
    let paths: Vec<PathBuf> = names.iter().map(|n| cwd.join(n)).collect();
    do_delete(a, paths);
}

pub fn unpack(a: &mut App, item: &Item) {
    a.message = Some("Unpacking...".to_string());
    let start = Instant::now();
    let r = crate::codec::unpack(&item.path, &a.cwd);
    match r {
        Ok(outdir) => {
            let _ = outdir;
            a.message = Some(format!("Unpacked. [{:.2}s]", start.elapsed().as_secs_f64()));
        }
        Err(e) => {
            a.message = Some(format!("{}", e));
        }
    }
    a.reload();
    a.need_full = true;
}
