// ---------------- session ----------------

#[derive(PartialEq, Clone, Copy)]
pub enum SortBy {
    Name,
    Time,
}

pub fn load_session(a: &mut App) {
    let p = data_dir().join(".session");
    if let Ok(s) = std::fs::read_to_string(&p) {
        let mut sort_name = true;
        let mut hidden = true;
        let mut preview = false;
        let mut vertical = true;
        for line in s.lines() {
            let mut it = line.splitn(2, ':');
            let k = it.next().unwrap_or("").trim();
            let v = it.next().unwrap_or("").trim();
            match k {
                "sort_by" => sort_name = v == "Name",
                "show_hidden" => hidden = v == "true",
                "preview" => preview = v == "true",
                "split" => vertical = v == "Vertical",
                _ => {}
            }
        }
        a.sort_by_name = sort_name;
        a.show_hidden = hidden;
        a.preview = preview;
        a.split = if vertical { crate::app::Split::Vertical } else { crate::app::Split::Horizontal };
    }
}

pub fn save_session(a: &App) {
    let d = data_dir();
    let _ = std::fs::create_dir_all(&d);
    let s = format!(
        "sort_by: {}\nshow_hidden: {}\npreview: {}\nsplit: {}\n",
        if a.sort_by_name { "Name" } else { "Time" },
        a.show_hidden,
        a.preview,
        if a.split == crate::app::Split::Vertical { "Vertical" } else { "Horizontal" }
    );
    let _ = std::fs::write(d.join(".session"), s);
}

// ---------------- logging ----------------

pub struct Logger {
    file: Option<std::fs::File>,
}

impl Logger {
    pub fn new() -> Logger {
        Logger { file: None }
    }
    pub fn start(&mut self) {
        let d = log_dir();
        let _ = std::fs::create_dir_all(&d);
        let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|x| x.as_secs()).unwrap_or(0);
        let (y, mo, dd, h, mi, se) = civil6(now as i64);
        let name = format!("{:04}-{:02}-{:02}-{:02}-{:02}-{:02}.log", y, mo, dd, h, mi, se);
        if let Ok(f) = std::fs::OpenOptions::new().create(true).append(true).write(true).open(d.join(name)) {
            self.file = Some(f);
            self.info("===START===");
        }
    }
    fn write(&mut self, level: &str, msg: &str) {
        use std::io::Write;
        if let Some(f) = self.file.as_mut() {
            let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|x| x.as_secs()).unwrap_or(0);
            let (_, _, _, h, mi, se) = civil6(now as i64);
            let _ = writeln!(f, "{:02}:{:02}:{:02} [{}] {}", h, mi, se, level, msg);
            let _ = f.flush();
        }
    }
    pub fn info(&mut self, msg: &str) {
        self.write("INFO", msg);
    }
    pub fn warn(&mut self, msg: &str) {
        self.write("WARN", msg);
    }
}

pub fn civil6(secs: i64) -> (i64, u32, u32, u32, u32, u32) {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let h = (rem / 3600) as u32;
    let mi = ((rem % 3600) / 60) as u32;
    let se = (rem % 60) as u32;
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as i64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d, h, mi, se)
}

