pub fn do_delete(a: &mut App, paths: Vec<PathBuf>) {
    if paths.is_empty() {
        return;
    }
    a.message = Some("DELETE: Processing...".to_string());
    a.draw();
    a.flush();
    let t = crate::ops::now_secs();
    let mut trash_paths = Vec::new();
    for p in &paths {
        let name = p.file_name().map(|x| x.to_string_lossy().into_owned()).unwrap_or_default();
        let tp = trash_dir().join(format!("{}_{}", t, name));
        let r = std::fs::rename(p, &tp);
        match r {
            Ok(_) => trash_paths.push(tp),
            Err(e) => {
                a.message = Some(err_str(e));
            }
        }
    }
    if a.log {
        let names: Vec<String> = paths.iter().map(|p| format!("\"{}\"", p.display())).collect();
        crate::LOGGER.info(&format!("DELETE: [{}]", names.join(", ")));
    }
    // undo bookkeeping
    let op = Op::Delete { paths: paths.clone(), trash: trash_paths.clone() };
    a.undo.push(op);
    a.redo.clear();
    a.reload();
    let n = trash_paths.len();
    let el = elapsed_str();
    let msg = if n == 1 {
        format!("1 item deleted. [{}]", el)
    } else {
        format!("{} items deleted [{}]", n, el)
    };
    if a.log {
        crate::LOGGER.info(&msg);
    }
    a.message = Some(msg);
    a.need_full = true;
    a.draw();
    a.flush();
}

