    }
    a.message = Some(msg);
    a.need_full = true;
}

pub fn stem_of(n: &str) -> String {
    match n.rfind('.') {
        Some(i) if i > 0 => n[..i].to_string(),
        _ => n.to_string(),
    }
}
pub fn ext_of(n: &str) -> String {
    match n.rfind('.') {
        Some(i) if i + 1 < n.len() => n[i + 1..].to_string(),
        _ => String::new(),
    }
}

pub fn elapsed_str() -> String {
    let d = START.elapsed();
    format!("{:.2}s", d.as_secs_f64())
}

pub fn copy_recursive(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = std::fs::symlink_metadata(src)?;
    if meta.file_type().is_symlink() {
        let t = std::fs::read_link(src)?;
        return std::os::unix::fs::symlink(t, dst);
    }
    if meta.is_dir() {
        std::fs::create_dir(dst)?;
        for e in std::fs::read_dir(src)? {
            let e = e?;
            copy_recursive(&e.path(), &dst.join(e.file_name()))?;
        }
        Ok(())
    } else {
        std::fs::copy(src, dst)?;
        Ok(())
    }
}

pub fn undo_op(a: &mut App) {
    if a.undo.is_empty() {
        a.message = Some("No operations left.".to_string());
        return;
    }
    let op = a.undo.pop().unwrap();
    match op {
        Op::Put { paths } => {
            for p in &paths {
                let r = if p.is_dir() { std::fs::remove_dir_all(p) } else { std::fs::remove_file(p) };
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("UNDONE: PUT".to_string());
            a.redo.push(Op::Put { paths });
        }
        Op::Delete { paths, trash } => {
            for (p, t) in paths.iter().zip(trash.iter()) {
                let r = std::fs::copy(t, p);
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("UNDONE: DELETE".to_string());
            a.redo.push(Op::Delete { paths, trash });
        }
        Op::Rename { from, to } => {
            for (f, t) in from.iter().zip(to.iter()) {
                let r = std::fs::rename(t, f);
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("UNDONE: RENAME".to_string());
            a.redo.push(Op::Rename { from, to });
        }
    }
    if a.log {
        crate::LOGGER.info("UNDONE");
    }
    a.reload();
    a.need_full = true;
}

pub fn redo_op(a: &mut App) {
    if a.redo.is_empty() {
        a.message = Some("No operations left.".to_string());
        return;
    }
    let op = a.redo.pop().unwrap();
    match op {
        Op::Put { paths } => {
            // need source from trash: we stored destinations only; re-copy from trash by name
            for p in &paths {
                let name = p.file_name().unwrap_or_default().to_string_lossy().to_string();
                if let Some(t) = find_trash_by_name(&name) {
                    let _ = copy_recursive(&t, p);
                }
            }
            a.message = Some("REDONE: PUT".to_string());
            a.undo.push(Op::Put { paths });
        }
        Op::Delete { paths, trash } => {
            for p in &paths {
                let r = if p.is_dir() { std::fs::remove_dir_all(p) } else { std::fs::remove_file(p) };
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("REDONE DELETE".to_string());
            a.undo.push(Op::Delete { paths, trash });
        }
        Op::Rename { from, to } => {
            for (f, t) in from.iter().zip(to.iter()) {
                let r = std::fs::rename(f, t);
                if let Err(e) = r {
                    a.message = Some(err_str(e));
                }
            }
            a.message = Some("REDONE: RENAME".to_string());
            a.undo.push(Op::Rename { from, to });
        }
    }
    a.reload();
    a.need_full = true;
}

pub fn find_trash_by_name(name: &str) -> Option<PathBuf> {
    let mut best: Option<(u64, PathBuf)> = None;
    if let Ok(rd) = std::fs::read_dir(trash_dir()) {
        for e in rd.flatten() {
            let f = e.file_name().to_string_lossy().to_string();
            if let Some(idx) = f.find('_') {
                if &f[idx + 1..] == name {
                    if let Ok(n) = f[..idx].parse::<u64>() {
                        if best.as_ref().map(|(b, _)| n > *b).unwrap_or(true) {
                            best = Some((n, e.path()));
                        }
                    }
                }
            }
        }
    }
    best.map(|(_, p)| p)
}

pub fn do_create(a: &mut App, name: &str, is_dir: bool) {
    let p = a.cwd.join(name);
    let r = if is_dir { std::fs::create_dir(&p) } else { std::fs::File::create(&p).map(|_| ()) };
    match r {
        Ok(_) => {
            a.reload();
            if let Some(i) = a.items.iter().position(|x| x.name == name) {
                a.cursor = i;
            }
            a.fix_offset();
            a.need_full = true;
        }
        Err(e) => {
            a.message = Some(err_str(e));
        }
    }
}

pub fn do_rename(a: &mut App, from: PathBuf, new: &str) {
    let to = a.cwd.join(new);
    if from == to {
        let op = Op::Rename { from: vec![from.clone()], to: vec![to.clone()] };
        a.undo.push(op);
        a.redo.clear();
        return;
    }
    match std::fs::rename(&from, &to) {
        Ok(_) => {
            let op = Op::Rename { from: vec![from], to: vec![to] };
            a.undo.push(op);
            a.redo.clear();
            a.reload();
            a.need_full = true;
        }
        Err(e) => {
            a.message = Some(err_str(e));
            a.reload();
            a.need_full = true;
        }
    }
}

pub fn empty_trash(a: &mut App) {
    let r = std::fs::read_dir(trash_dir());
    let mut n = 0;
    if let Ok(rd) = r {
        for e in rd.flatten() {
            let p = e.path();
            let rr = if p.is_dir() { std::fs::remove_dir_all(&p) } else { std::fs::remove_file(&p) };
            if rr.is_ok() {
                n += 1;
            }
        }
    }
    a.message = Some(format!("Deleted {} items from the trash directory.", n));
}

pub fn yank(a: &mut App, names: Vec<String>, reg: Option<char>, append: bool) {
    // store into registers
    set_register(a, reg, names.clone(), append);
    let n = names.len();
    let msg = if n == 1 { "1 item yanked.".to_string() } else { format!("{} items yanked", n) };
    a.message = Some(msg);
}

pub fn set_register(a: &mut App, reg: Option<char>, names: Vec<String>, append: bool) {
    let key = match reg {
        Some(c) => c.to_string(),
        None => "0".to_string(),
    };
    if let Some(e) = a.registers.iter_mut().find(|(k, _)| *k == key) {
        if append {
            e.1.extend(names);
        } else {
            e.1 = names;
        }
    } else {
        a.registers.push((key, names));
    }
    // unnamed register
    if let Some(e) = a.registers.iter_mut().find(|(k, _)| k.is_empty()) {
        if append {
            e.1.extend(names);
        } else {
            e.1 = names;
        }
    } else {
        let mut v = names;
        let e = (String::new(), std::mem::take(&mut v));
        a.registers.insert(0, e);
    }
}

pub fn get_register(regs: &[(String, Vec<String>)], key: &str) -> Vec<String> {
    if let Some((_, v)) = regs.iter().find(|(k, _)| k == key) {
        v.clone()
    } else {
        Vec::new()
    }
}

