#[derive(Debug, Clone)]
enum Y {
    Str(String),
    Map(Vec<(String, Y)>),
    Seq(Vec<Y>),
    Null,
}

impl Y {
    fn as_str(&self) -> Option<&str> {
        match self {
            Y::Str(s) => Some(s),
            _ => None,
        }
    }
    fn get(&self, k: &str) -> Option<&Y> {
        match self {
            Y::Map(m) => m.iter().find(|(a, _)| a == k).map(|(_, v)| v),
            _ => None,
        }
    }
}

fn parse_color(s: &str) -> Option<u8> {
