fn parse_block(lines: &[&str], i: &mut usize, indent: usize) -> Result<Y, String> {
    // decide map or seq by first significant line
    while *i < lines.len() {
        let l = lines[*i];
        let t = l.trim();
        if t.is_empty() || t.starts_with('#') {
            *i += 1;
            continue;
        }
        if indent_of(l) < indent {
            return Ok(Y::Null);
        }
        if t.starts_with("- ") || t == "-" {
            let mut seq = Vec::new();
            while *i < lines.len() {
                let l2 = lines[*i];
                let t2 = l2.trim();
                if t2.is_empty() {
                    *i += 1;
                    continue;
                }
                if indent_of(l2) < indent {
                    break;
                }
                if !(t2.starts_with("- ") || t2 == "-") {
                    break;
                }
                let rest = t2[1..].trim();
                seq.push(Y::Str(unquote(rest)));
                *i += 1;
            }
            return Ok(Y::Seq(seq));
        }
        // map
        let mut map: Vec<(String, Y)> = Vec::new();
        while *i < lines.len() {
            let l = lines[*i];
            let t = l.trim();
            if t.is_empty() || t.starts_with('#') {
                *i += 1;
                continue;
            }
            let ind = indent_of(l);
            if ind < indent {
                break;
            }
            if ind > indent {
                return Err(format!("unexpected indentation at line {}", *i + 1));
            }
            let colon = match t.find(':') {
                Some(c) => c,
                None => return Err(format!("could not find expected ':' at line {}", *i + 1)),
            };
            let key = unquote(t[..colon].trim());
            let rest = t[colon + 1..].trim();
            *i += 1;
            if rest.is_empty() {
                // nested block
                let child_indent = if *i < lines.len() { indent_of(lines[*i]) } else { 0 };
                if *i < lines.len() && indent_of(lines[*i]) > indent {
                    let v = parse_block(lines, i, child_indent)?;
                    map.push((key, v));
                } else {
                    map.push((key, Y::Null));
                }
            } else if rest.starts_with('[') {
                if !rest.ends_with(']') {
                    return Err(format!("did not find expected ',' or ']' at line {}", *i));
                }
                let inner = &rest[1..rest.len() - 1];
                let items: Vec<Y> = inner
                    .split(',')
                    .filter(|x| !x.trim().is_empty())
                    .map(|x| Y::Str(unquote(x.trim())))
                    .collect();
                map.push((key, Y::Seq(items)));
            } else {
                map.push((key, Y::Str(unquote(rest))));
            }
        }
        return Ok(Y::Map(map));
    }
    Ok(Y::Null)
}

fn unquote(s: &str) -> String {
    let s = s.trim();
    if s.len() >= 2 && ((s.starts_with('"') && s.ends_with('"')) || (s.starts_with('\'') && s.ends_with('\''))) {
        s[1..s.len() - 1].to_string()
    } else {
        s.to_string()
    }
}

pub fn load() -> Config {
    let mut cfg = Config::default();
    let d = crate::ops::config_dir();
    let mut path = d.join("config.yaml");
    if !path.exists() {
        let p2 = d.join("config.yml");
        if p2.exists() {
            path = p2;
        } else {
            return cfg;
        }
    }
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(_) => return cfg,
    };
    match parse_yaml(&text) {
        Ok(Y::Map(m)) => {
            for (k, v) in m {
                match k.as_str() {
                    "color" => {
                        if let Y::Map(cm) = &v {
                            for (ck, cv) in cm {
                                let val = cv.as_str().and_then(parse_color);
                                match ck.as_str() {
                                    "dir_fg" => {
                                        if let Some(x) = val {
                                            cfg.colors.dir_fg = x
                                        }
                                    }
                                    "file_fg" => {
                                        if let Some(x) = val {
                                            cfg.colors.file_fg = x
                                        }
                                    }
                                    "symlink_fg" => {
                                        if let Some(x) = val {
                                            cfg.colors.symlink_fg = x
                                        }
                                    }
                                    "dirty_fg" => {
                                        if let Some(x) = val {
                                            cfg.colors.dirty_fg = x
                                        }
                                    }
                                    _ => {
                                        eprintln!("Cannot read the config file properly.");
                                        eprintln!("Error: color: unknown field `{}`", ck);
                                        eprintln!("felix launches with default configuration.");
                                        return Config::default();
                                    }
                                }
                            }
                        }
                    }
                    "match_vim_exit_behavior" => {
                        cfg.match_vim_exit_behavior = v.as_str() == Some("true");
                    }
                    "default" => {
                        cfg.default = v.as_str().unwrap_or("").to_string();
                    }
                    _ => {}
                }
            }
        }
        Ok(_) => {}
        Err(e) => {
            println!("Cannot read the config file properly.");
            println!("Error: {}", e);
            println!("felix launches with default configuration.");
        }
    }
    cfg
}
