mod app;
mod codec;
mod config;
mod draw;
mod help;
mod list;
mod ops;
mod term;

use app::{App, InputKind, Mode, Split};
use std::path::PathBuf;
use term::{Key, Term};

const fn is_flag(a: &str) -> bool {
    a == "-h" || a == "--help" || a == "--init" || a == "-l" || a == "--log"
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.len() > 2 {
        print_help();
        return;
    }
    if args.is_empty() {
        run(PathBuf::from("."), false);
        return;
    }
    match args[0].as_str() {
        "-h" | "--help" => {
            print_help();
        }
        "--init" => {
            if args.len() == 1 {
                print!("{}", crate::help::INIT);
            } else {
                print_help();
            }
        }
        "-l" | "--log" => {
            if args.len() == 1 {
                run(PathBuf::from("."), true);
            } else {
                run(PathBuf::from(&args[1]), true);
            }
        }
        p => {
            if args.len() == 1 {
                run(PathBuf::from(p), false);
            } else {
                print_help();
            }
        }
    }
}

fn print_help() {
    print!("{}", crate::help::HELP);
}

fn invalid_path(p: &str) {
    eprintln!();
    eprintln!("Invalid path: {}", p);
    eprintln!("`fx -h` shows help.");
}

fn not_directory() {
    eprintln!("Path should be directory.");
    eprintln!("`fx -h` shows help.");
}

fn run(path: PathBuf, log: bool) {
    let abs = std::fs::canonicalize(&path);
    let p = match abs {
        Ok(p) => p,
        Err(_) => {
            invalid_path(&path.to_string_lossy());
            return;
        }
    };
    if !p.is_dir() {
        not_directory();
        return;
    }
    let mut term = match Term::new() {
        Some(t) => t,
        None => {
            eprintln!("Error: Cannot detect terminal size");
            return;
        }
    };
    let size = match term.size() {
        Some(s) => s,
        None => {
            eprintln!("Error: Cannot detect terminal size");
            return;
        }
    };
    if size.0 == 0 || size.1 == 0 {
        eprintln!("Error: Cannot detect terminal size");
        return;
    }
    let _ = size;
    if !term.enable_raw() {
        eprintln!("Error: Cannot enable raw mode");
        return;
    }
    if log {
        crate::LOGGER.lock().start();
    }
    crate::ops::ensure_dirs();
    let mut a = App::new(term, p.clone(), log);
    a.startup();
    a.draw();
    a.flush();
    let mut keys = term::Keys::new();
    loop {
        let k = match keys.next() {
            Some(k) => k,
            None => break,
        };
        if !handle(&mut a, k) {
            break;
        }
        a.draw();
        a.flush();
    }
    a.teardown();
    crate::ops::save_session(&a);
}

fn handle(a: &mut App, k: Key) -> bool {
    // pending key handling
    if let Some(p) = a.pending.take() {
        return handle_pending(a, p, k);
    }
    match &a.mode {
        Mode::Normal => handle_normal(a, k),
        Mode::Search { .. } => handle_search(a, k),
        Mode::Command { .. } => handle_command(a, k),
        Mode::Input { .. } => handle_input(a, k),
        Mode::Visual { .. } => handle_visual(a, k),
    }
}

fn handle_pending(a: &mut App, p: char, k: Key) -> bool {
    match p {
        'd' => {
            if let Key::Char('d') = k {
                let names = vec![a.items[a.cursor].name.clone()];
                crate::ops::delete_and_yank(a, names, None, false);
            } else {
                a.message = None;
                if let Key::Esc = k {
                    a.term.write(b"\x1b[?25l");
                }
            }
            true
        }
        'y' => {
            if let Key::Char('y') = k {
                let names = vec![a.items[a.cursor].name.clone()];
                crate::ops::yank(a, names, None, false);
            } else {
                a.message = None;
                if let Key::Esc = k {
                    a.term.write(b"\x1b[?25l");
                }
            }
            true
        }
        'g' => {
            if let Key::Char('g') = k {
                a.cursor = 0;
                a.fix_offset();
                a.need_full = true;
            }
            true
        }
        'Z' => {
            if let Key::Char('Z') = k {
                a.pending_exit();
                return false;
            }
            if let Key::Char('Q') = k {
                if a.cfg_match_vim() {
                    a.pending_exit();
                } else {
                    a.zq_exit();
                }
                return false;
            }
            true
        }
        '"' => {
            if let Key::Char(c) = k {
                a.reg_sel = Some(c);
                a.draw_input_line(&format!("\"{}", c), true);
                a.pending = Some('\u{0}');
                // handled below via reg state
                a.reg_wait = true;
                return true;
            }
            true
        }
        _ => true,
    }
}

fn handle_normal(a: &mut App, k: Key) -> bool {
    match k {
        Key::Char('j') | Key::Down => {
            if a.cursor + 1 < a.items.len() {
                a.cursor += 1;
                a.fix_offset();
            }
        }
        Key::Char('k') | Key::Up => {
            if a.cursor > 0 {
                a.cursor -= 1;
                a.fix_offset();
            }
        }
        Key::Ctrl('d') => {
            let n = (a.h / 2) as usize;
            let old = a.cursor;
            a.cursor = (a.cursor + n).min(a.items.len().saturating_sub(1));
            a.fix_offset();
            if a.cursor != old {
                a.need_full = true;
            }
        }
        Key::Ctrl('u') => {
            let n = (a.h / 2) as usize;
            let old = a.cursor;
            a.cursor = a.cursor.saturating_sub(n);
            a.fix_offset();
            if a.cursor != old {
                a.need_full = true;
            }
        }
        Key::Char('h') | Key::Left => {
            a.go_parent();
        }
        Key::Char('l') | Key::Right | Key::Enter => {
            a.open_item();
        }
        Key::Char('g') => {
            a.pending = Some('g');
            a.draw_input_line("g", true);
            return true;
        }
        Key::Char('G') => {
            a.cursor = a.items.len().saturating_sub(1);
            a.offset = a.items.len().saturating_sub(a.layout.rows.max(1) as usize);
            a.fix_offset();
            a.need_full = true;
        }
        Key::Ctrl('o') => {
            a.jump_back();
        }
        Key::Tab | Key::Ctrl('i') => {
            a.jump_forward();
        }
        Key::Char('i') => {
            a.start_input(InputKind::NewFile, "");
        }
        Key::Char('I') => {
            a.start_input(InputKind::NewDir, "");
        }
        Key::Char('o') => {
            a.open_window();
        }
        Key::Char('e') => {
            a.unpack_item();
        }
        Key::Char('d') => {
            a.pending = Some('d');
            a.draw_input_line("d", true);
            return true;
        }
        Key::Char('y') => {
            a.pending = Some('y');
            a.draw_input_line("y", true);
            return true;
        }
        Key::Char('p') => {
            let names = crate::ops::get_register(&a.registers, "0");
            crate::ops::do_put(a, &a.registers, "0");
        }
        Key::Char('"') => {
            a.pending = Some('"');
            a.draw_input_line("\"", true);
            return true;
        }
        Key::Char('V') => {
            a.mode = Mode::Visual { start: a.cursor };
            a.need_full = true;
        }
        Key::Ctrl('r') => {
            crate::ops::redo_op(a);
            a.fix_offset();
        }
        Key::Char('u') => {
            crate::ops::undo_op(a);
            a.fix_offset();
        }
        Key::Char('v') => {
            if a.show_reg {
                a.draw();
                a.show_reg = false;
                a.layout = a.compute_layout();
                a.need_full = true;
                return true;
            }
            a.preview = !a.preview;
            a.need_full = true;
            a.refresh_preview();
        }
        Key::Char('s') => {
            if a.preview {
                a.split = if a.split == Split::Vertical { Split::Horizontal } else { Split::Vertical };
                a.need_full = true;
            }
        }
        Key::AltChar('j') | Key::Alt(Key::Down) => {
            a.preview_scroll += 1;
        }
        Key::AltChar('k') | Key::Alt(Key::Up) => {
            a.preview_scroll = a.preview_scroll.saturating_sub(1);
        }
        Key::Backspace | Key::Ctrl('h') => {
            a.show_hidden = !a.show_hidden;
            a.reload();
            a.need_full = true;
        }
        Key::Char('t') => {
            a.sort_by_name = !a.sort_by_name;
            a.reload();
            a.need_full = true;
        }
        Key::Char('c') => {
            let name = a.items.get(a.cursor).map(|i| i.name.clone()).unwrap_or_default();
            a.start_input(InputKind::Rename, &name);
        }
        Key::Char('/') => {
            a.mode = Mode::Search { input: String::new() };
            a.draw_input_line("/", true);
            return true;
        }
        Key::Char('n') => {
