        Err(_) => {
            invalid_path(&path.to_string_lossy());
            return;
        }
    };
    if !p.is_dir() {
        not_directory();
        return;
    }
    let mut term = match Term::new() {
        Some(t) => t,
        None => {
            eprintln!("Error: Cannot detect terminal size");
            return;
        }
    };
    let size = match term.size() {
        Some(s) => s,
        None => {
            eprintln!("Error: Cannot detect terminal size");
            return;
        }
    };
    if size.0 == 0 || size.1 == 0 {
        eprintln!("Error: Cannot detect terminal size");
        return;
    }
    let _ = size;
    if !term.enable_raw() {
        eprintln!("Error: Cannot enable raw mode");
        return;
    }
