                a.show_reg = false;
                a.layout = a.compute_layout();
                a.need_full = true;
                return true;
            }
            a.preview = !a.preview;
            a.need_full = true;
            a.refresh_preview();
        }
        Key::Char('s') => {
            if a.preview {
                a.split = if a.split == Split::Vertical { Split::Horizontal } else { Split::Vertical };
