            }
        }
        Key::AltChar('j') | Key::Alt(Key::Down) => {
            a.preview_scroll += 1;
        }
        Key::AltChar('k') | Key::Alt(Key::Up) => {
            a.preview_scroll = a.preview_scroll.saturating_sub(1);
        }
        Key::Backspace | Key::Ctrl('h') => {
            a.show_hidden = !a.show_hidden;
            a.reload();
            a.need_full = true;
        }
        Key::Char('t') => {
            a.sort_by_name = !a.sort_by_name;
            a.reload();
            a.need_full = true;
        }
