        Mode::Input { .. } => handle_input(a, k),
        Mode::Visual { .. } => handle_visual(a, k),
    }
}

fn handle_pending(a: &mut App, p: char, k: Key) -> bool {
    match p {
        'd' => {
            if let Key::Char('d') = k {
                let names = vec![a.items[a.cursor].name.clone()];
                crate::ops::delete_and_yank(a, names, None, false);
            } else {
                a.message = None;
                if let Key::Esc = k {
                    a.term.write(b"\x1b[?25l");
                }
            }
            true
        }
        'y' => {
            if let Key::Char('y') = k {
                let names = vec![a.items[a.cursor].name.clone()];
                crate::ops::yank(a, names, None, false);
            } else {
                a.message = None;
                if let Key::Esc = k {
                    a.term.write(b"\x1b[?25l");
                }
            }
            true
        }
        'g' => {
            if let Key::Char('g') = k {
                a.cursor = 0;
                a.fix_offset();
                a.need_full = true;
            }
            true
        }
        'Z' => {
            if let Key::Char('Z') = k {
                a.pending_exit();
                return false;
            }
            if let Key::Char('Q') = k {
                if a.cfg_match_vim() {
                    a.pending_exit();
                } else {
                    a.zq_exit();
                }
                return false;
            }
            true
        }
        '"' => {
            if let Key::Char(c) = k {
                a.reg_sel = Some(c);
                a.draw_input_line(&format!("\"{}", c), true);
                a.pending = Some('\u{0}');
                // handled below via reg state
                a.reg_wait = true;
                return true;
            }
            true
        }
        _ => true,
    }
}

fn handle_normal(a: &mut App, k: Key) -> bool {
    match k {
        Key::Char('j') | Key::Down => {
            if a.cursor + 1 < a.items.len() {
                a.cursor += 1;
                a.fix_offset();
            }
        }
        Key::Char('k') | Key::Up => {
            if a.cursor > 0 {
                a.cursor -= 1;
                a.fix_offset();
            }
        }
        Key::Ctrl('d') => {
            let n = (a.h / 2) as usize;
            let old = a.cursor;
            a.cursor = (a.cursor + n).min(a.items.len().saturating_sub(1));
            a.fix_offset();
            if a.cursor != old {
                a.need_full = true;
            }
        }
        Key::Ctrl('u') => {
            let n = (a.h / 2) as usize;
            let old = a.cursor;
            a.cursor = a.cursor.saturating_sub(n);
            a.fix_offset();
            if a.cursor != old {
                a.need_full = true;
            }
        }
        Key::Char('h') | Key::Left => {
            a.go_parent();
        }
        Key::Char('l') | Key::Right | Key::Enter => {
            a.open_item();
        }
        Key::Char('g') => {
            a.pending = Some('g');
            a.draw_input_line("g", true);
            return true;
        }
        Key::Char('G') => {
            a.cursor = a.items.len().saturating_sub(1);
            a.offset = a.items.len().saturating_sub(a.layout.rows.max(1) as usize);
            a.fix_offset();
            a.need_full = true;
        }
        Key::Ctrl('o') => {
            a.jump_back();
        }
        Key::Tab | Key::Ctrl('i') => {
            a.jump_forward();
        }
        Key::Char('i') => {
            a.start_input(InputKind::NewFile, "");
        }
        Key::Char('I') => {
            a.start_input(InputKind::NewDir, "");
        }
        Key::Char('o') => {
            a.open_window();
        }
        Key::Char('e') => {
            a.unpack_item();
        }
        Key::Char('d') => {
            a.pending = Some('d');
            a.draw_input_line("d", true);
            return true;
        }
        Key::Char('y') => {
            a.pending = Some('y');
            a.draw_input_line("y", true);
            return true;
        }
        Key::Char('p') => {
            let names = crate::ops::get_register(&a.registers, "0");
            crate::ops::do_put(a, &a.registers, "0");
        }
        Key::Char('"') => {
            a.pending = Some('"');
            a.draw_input_line("\"", true);
            return true;
        }
        Key::Char('V') => {
            a.mode = Mode::Visual { start: a.cursor };
            a.need_full = true;
        }
        Key::Ctrl('r') => {
            crate::ops::redo_op(a);
            a.fix_offset();
        }
        Key::Char('u') => {
            crate::ops::undo_op(a);
            a.fix_offset();
        }
        Key::Char('v') => {
            if a.show_reg {
                a.draw();
                a.show_reg = false;
                a.layout = a.compute_layout();
                a.need_full = true;
                return true;
            }
            a.preview = !a.preview;
            a.need_full = true;
            a.refresh_preview();
        }
        Key::Char('s') => {
            if a.preview {
                a.split = if a.split == Split::Vertical { Split::Horizontal } else { Split::Vertical };
                a.need_full = true;
            }
        }
        Key::AltChar('j') | Key::Alt(Key::Down) => {
            a.preview_scroll += 1;
        }
        Key::AltChar('k') | Key::Alt(Key::Up) => {
            a.preview_scroll = a.preview_scroll.saturating_sub(1);
        }
        Key::Backspace | Key::Ctrl('h') => {
            a.show_hidden = !a.show_hidden;
            a.reload();
            a.need_full = true;
        }
        Key::Char('t') => {
            a.sort_by_name = !a.sort_by_name;
            a.reload();
            a.need_full = true;
        }
        Key::Char('c') => {
            let name = a.items.get(a.cursor).map(|i| i.name.clone()).unwrap_or_default();
            a.start_input(InputKind::Rename, &name);
        }
        Key::Char('/') => {
            a.mode = Mode::Search { input: String::new() };
            a.draw_input_line("/", true);
            return true;
        }
        Key::Char('n') => {
            a.search_jump(1);
        }
        Key::Char('N') => {
            a.search_jump(-1);
        }
        Key::Char(':') => {
            a.mode = Mode::Command { input: String::new() };
            a.draw_input_line(":", true);
            return true;
        }
        Key::Char('z') => {
            a.message = Some(msg_err("zoxide not found."));
        }
        Key::Esc => {
            a.message = None;
        }
        Key::Char('Z') => {
            a.pending = Some('Z');
            a.draw_input_line("Z", true);
            return true;
        }
        Key::Ctrl('c') => {
            return false;
        }
        _ => {}
    }
    true
}

pub fn msg_err(s: &str) -> String {
    format!("\x1b[38;5;7m\x1b[48;5;9m{}\x1b[0m", s)
}

fn handle_search(a: &mut App, k: Key) -> bool {
    let input = match &a.mode {
        Mode::Search { input } => input.clone(),
        _ => return true,
    };
    match k {
        Key::Char(c) => {
            let mut s = input;
            s.push(c);
            a.mode = Mode::Search { input: s };
            a.apply_search(true);
        }
        Key::Backspace | Key::Ctrl('h') => {
            let mut s = input;
            s.pop();
            a.mode = Mode::Search { input: s };
            a.apply_search(true);
        }
        Key::Enter => {
            let s = input;
            a.search_word = s.clone();
            a.apply_search(false);
            a.mode = Mode::Normal;
        }
        Key::Esc => {
            a.mode = Mode::Normal;
            a.message = None;
        }
        Key::Ctrl('c') => return false,
        _ => {}
    }
    true
}

fn handle_command(a: &mut App, k: Key) -> bool {
    let input = match &a.mode {
        Mode::Command { input } => input.clone(),
        _ => return true,
    };
    match k {
        Key::Char(c) => {
            let mut s = input;
            s.push(c);
            a.mode = Mode::Command { input: s };
            a.draw_command(&s);
            return true;
        }
        Key::Backspace | Key::Ctrl('h') => {
            let mut s = input;
            s.pop();
            a.mode = Mode::Command { input: s.clone() };
            a.draw_command(&s);
            return true;
        }
        Key::Enter => {
            let s = input;
            a.mode = Mode::Normal;
            a.exec_command(&s);
        }
        Key::Esc => {
            a.mode = Mode::Normal;
            a.message = None;
        }
        Key::Ctrl('c') => return false,
        _ => {}
    }
    true
}

fn handle_input(a: &mut App, k: Key) -> bool {
    let (kind, mut input) = match &a.mode {
        Mode::Input { kind, input } => (kind.clone(), input.clone()),
        _ => return true,
    };
    match k {
        Key::Char(c) => {
            input.push(c);
            a.mode = Mode::Input { kind: kind.clone(), input: input.clone() };
            a.redraw_input();
        }
        Key::Backspace | Key::Ctrl('h') => {
            input.pop();
            a.mode = Mode::Input { kind: kind.clone(), input: input.clone() };
            a.redraw_input();
        }
        Key::Enter => {
            a.mode = Mode::Normal;
            a.finish_input(&kind, &input);
        }
        Key::Esc => {
            a.mode = Mode::Normal;
            a.message = None;
        }
        Key::Ctrl('c') => return false,
        _ => {}
    }
    true
}

fn handle_visual(a: &mut App, k: Key) -> bool {
    let start = match &a.mode {
        Mode::Visual { start } => *start,
        _ => return true,
    };
    match k {
        Key::Char('j') | Key::Down => {
            if a.cursor + 1 < a.items.len() {
                a.cursor += 1;
                a.fix_offset();
                a.need_full = true;
            }
        }
        Key::Char('k') | Key::Up => {
            if a.cursor > 0 {
                a.cursor -= 1;
                a.fix_offset();
                a.need_full = true;
            }
        }
        Key::Ctrl('d') => {
            let n = (a.h / 2) as usize;
            a.cursor = (a.cursor + n).min(a.items.len().saturating_sub(1));
            a.fix_offset();
            a.need_full = true;
        }
        Key::Ctrl('u') => {
            let n = (a.h / 2) as usize;
            a.cursor = a.cursor.saturating_sub(n);
            a.fix_offset();
            a.need_full = true;
        }
        Key::Char('y') => {
            let names = a.visual_names(start);
            a.mode = Mode::Normal;
            crate::ops::yank(a, names, None, false);
            a.need_full = true;
        }
        Key::Char('d') => {
            let names = a.visual_names(start);
            a.mode = Mode::Normal;
            crate::ops::delete_and_yank(a, names, None, false);
            a.need_full = true;
        }
        Key::Char('"') => {
            a.pending = Some('"');
            a.draw_input_line("\"", true);
            return true;
        }
        Key::Esc => {
            a.mode = Mode::Normal;
            a.need_full = true;
        }
        Key::Ctrl('c') => return false,
        _ => {}
    }
    true
}
