                self.need_full = true;
            }
            "config" => {
                let d = crate::ops::config_dir();
                self.chdir(d.parent().unwrap_or(&d).to_path_buf());
                self.need_full = true;
            }
            "trash" => {
                self.chdir(crate::ops::trash_dir());
                self.need_full = true;
            }
            "empty" => {
                crate::ops::empty_trash(self);
                self.need_full = true;
            }
            "h" => {
                self.show_help = true;
                self.need_full = true;
            }
            "reg" => {
                self.show_reg = true;
                self.need_full = true;
            }
            _ => {
                self.run_shell(s);
            }
        }
    }

    pub fn run_shell(&mut self, s: &str) {
        use std::process::{Command, Stdio};
        self.term.write(b"\x1b[?25h\x1b[?1049l\x1b8");
        self.term.flush();
