        self.term.write(b"\x1b7\x1b[?25l\x1b[?1049h\x1b[2J");
        self.need_full = true;
        if let Err(e) = st {
            self.message = Some(format!("{}", e));
        }
        self.reload();
    }

    pub fn visual_cursor_row(&self) -> i32 {
        2 + (self.cursor as i32 - self.offset as i32)
    }
}
