        if w.is_empty() {
            return;
        }
        let n = self.items.len();
        if n == 0 {
            return;
        }
        let mut idx = self.cursor as i64;
        loop {
            idx += dir;
            if idx < 0 || idx >= n as i64 {
                return;
            }
            if self.items[idx as usize].name.contains(&w) {
                self.cursor = idx as usize;
                self.offset = self.cursor;
                self.fix_offset();
                self.need_full = true;
                return;
            }
        }
    }

    pub fn visual_names(&self, start: usize) -> Vec<String> {
        let (a, b) = if start <= self.cursor { (start, self.cursor) } else { (self.cursor, start) };
        self.items[a..=b.min(self.items.len().saturating_sub(1))]
            .iter()
            .map(|i| i.name.clone())
            .collect()
    }

    pub fn exec_command(&mut self, s: &str) {
        let parts: Vec<&str> = s.split_whitespace().collect();
        if parts.is_empty() {
            return;
        }
        match parts[0] {
            "q" => {
                self.pending_exit();
                std::process::exit(0);
            }
            "cd" => {
                if parts.len() == 1 {
                    let home = std::env::var("HOME").unwrap_or_default();
                    self.chdir(PathBuf::from(home));
                } else {
                    let p = PathBuf::from(parts[1..].join(" "));
                    let p = if p.is_absolute() { p } else { self.cwd.join(p) };
                    self.chdir(p);
                }
                self.need_full = true;
            }
            "e" => {
                self.reload();
                self.need_full = true;
            }
            "config" => {
                let d = crate::ops::config_dir();
                self.chdir(d.parent().unwrap_or(&d).to_path_buf());
                self.need_full = true;
            }
            "trash" => {
                self.chdir(crate::ops::trash_dir());
                self.need_full = true;
            }
            "empty" => {
                crate::ops::empty_trash(self);
                self.need_full = true;
            }
            "h" => {
                self.show_help = true;
                self.need_full = true;
            }
            "reg" => {
                self.show_reg = true;
                self.need_full = true;
            }
            _ => {
                self.run_shell(s);
            }
        }
    }

    pub fn run_shell(&mut self, s: &str) {
        use std::process::{Command, Stdio};
        self.term.write(b"\x1b[?25h\x1b[?1049l\x1b8");
        self.term.flush();
        let cwd = self.cwd.clone();
        let st = Command::new("sh").arg("-c").arg(s).current_dir(cwd).spawn().and_then(|mut c| c.wait());
        self.term.write(b"\x1b7\x1b[?25l\x1b[?1049h\x1b[2J");
        self.need_full = true;
        if let Err(e) = st {
            self.message = Some(format!("{}", e));
        }
        self.reload();
    }

    pub fn visual_cursor_row(&self) -> i32 {
        2 + (self.cursor as i32 - self.offset as i32)
    }
}
RSEOF
echo ok"}

