/// Query the cursor position by writing ESC[6n and reading the reply.
/// Returns (row, col) 1-based.
pub fn query_cursor() -> Option<(u16, u16)> {
    use std::time::{Duration, Instant};
    let start = Instant::now();
    let mut buf: Vec<u8> = Vec::new();
    while start.elapsed() < Duration::from_secs(2) {
        let mut b = [0u8; 256];
        let n = unsafe { read(0, b.as_mut_ptr(), b.len()) };
        if n <= 0 {
            std::thread::sleep(Duration::from_millis(5));
            continue;
        }
        buf.extend_from_slice(&b[..n as usize]);
        // look for ESC [ r ; c R
        if let Some(idx) = find_dsr(&buf) {
            let s = String::from_utf8_lossy(&buf[idx..]).to_string();
            let inner = &s[2..s.len() - 1];
            let mut it = inner.split(';');
            let r = it.next().and_then(|x| x.parse::<u16>().ok()).unwrap_or(1);
            let c = it.next().and_then(|x| x.parse::<u16>().ok()).unwrap_or(1);
            let used = idx + 2 + inner.len() + 1;
            // push back remaining bytes
            let rest: Vec<u8> = buf[used..].to_vec();
            PENDING.lock().unwrap().extend(rest);
            return Some((r, c));
        }
    }
    None
}

pub static PENDING: std::sync::Mutex<Vec<u8>> = std::sync::Mutex::new(Vec::new());

fn find_dsr(buf: &[u8]) -> Option<usize> {
    for i in 0..buf.len() {
        if buf[i] == 0x1b && i + 1 < buf.len() && buf[i + 1] == b'[' {
            // scan for 'R'
            let mut j = i + 2;
            while j < buf.len() && buf[j].is_ascii_digit() {
                j += 1;
            }
            if j < buf.len() && buf[j] == b';' {
                let mut k = j + 1;
                while k < buf.len() && buf[k].is_ascii_digit() {
                    k += 1;
                }
                if k < buf.len() && buf[k] == b'R' {
                    return Some(i);
                }
            }
        }
    }
    None
}
