new = '''pub fn do_delete(a: &mut App, paths: Vec<PathBuf>) {
    if paths.is_empty() {
        return;
    }
    let start = std::time::Instant::now();
    a.message = Some("DELETE: Processing...".to_string());
    a.erase_marker();
    a.draw_bottom_msg();
    a.draw_marker();
    a.flush();
    let t = crate::ops::now_secs();
    let mut trash_paths: Vec<PathBuf> = Vec::new();
    let n = paths.len();
    for (i, p) in paths.iter().enumerate() {
        let name = p.file_name().map(|x| x.to_string_lossy().into_owned()).unwrap_or_default();
        let tp = trash_dir().join(format!("{}_{}", t, name));
        match std::fs::rename(p, &tp) {
            Ok(_) => trash_paths.push(tp),
            Err(e) => {
                a.message = Some(crate::globals::err_string(e));
            }
        }
        // progress message
        let isdir = p.is_dir();
        let prog = format!("{}/{}", i + 1, n);
        let txt = if isdir { format!("{} [-----]", prog) } else { prog.clone() };
        a.erase_marker();
        a.out(&crate::draw::move_to(1, 1));
        a.out("\\x1b[2K");
        a.out(&txt);
        if isdir {
            a.out("\\x1b[7D");
        }
        if i + 1 == n {
            // last item: reload and draw
            a.reload();
            a.out("\\x1b[2J");
            a.draw_title();
            a.draw_items();
        }
        a.flush();
    }
    if a.log {
        let names: Vec<String> = paths.iter().map(|p| format!("\\"{}\\"", p.display())).collect();
        crate::globals::LOGGER.lock().unwrap().info(&format!("DELETE: [{}]", names.join(", ")));
    }
    let op = Op::Delete { paths: paths.clone(), trash: trash_paths.clone() };
    a.undo.push(op);
    a.redo.clear();
    let cnt = trash_paths.len();
    let el = elapsed_str_from(start.elapsed());
    let msg = if cnt == 1 {
        format!("1 item deleted. [{}]", el)
    } else {
        format!("{} items deleted [{}]", cnt, el)
    };
    if a.log {
        crate::globals::LOGGER.lock().unwrap().info(&msg);
    }
    if n > 1 {
        a.need_full = true;
    } else {
        a.need_full = false;
    }
    a.erase_marker();
    a.out(&crate::draw::move_to(1, 1));
    a.out("\\x1b[2K");
    a.out(&msg);
    a.out("\\x1b[?25l");
    a.draw_marker();
    a.message = Some(msg);
    a.msg_drawn = true;
    a.flush();
}

